using Microsoft.VisualStudio.TestTools.UnitTesting;
using Payments;

namespace Payments.Tests;

[TestClass]
public class PaymentGatewayTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new PaymentGateway();
    }

    // ── ChargeAsync ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(result.ChargeId));
    }

    [TestMethod]
    public async Task ChargeAsync_ReturnsUniqueChargeIds()
    {
        var r1 = await _gateway.ChargeAsync("tok_visa_1", 10m);
        var r2 = await _gateway.ChargeAsync("tok_visa_2", 20m);

        Assert.AreNotEqual(r1.ChargeId, r2.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_Fails()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 0m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_Fails()
    {
        var result = await _gateway.ChargeAsync("tok_valid", -5m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public async Task ChargeAsync_NullToken_ThrowsArgumentNullException()
    {
        await _gateway.ChargeAsync(null!, 10m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ChargeAsync_EmptyToken_ThrowsArgumentException()
    {
        await _gateway.ChargeAsync("", 10m);
    }

    [TestMethod]
    public async Task ChargeAsync_VeryLargeAmount_Fails()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 1_000_001m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(1.00)]
    [DataRow(999.99)]
    public async Task ChargeAsync_VariousValidAmounts_ReturnsSuccess(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    // ── RefundAsync ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccess()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 25m);
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(refund.RefundId));
    }

    [TestMethod]
    public async Task RefundAsync_InvalidChargeId_Fails()
    {
        var result = await _gateway.RefundAsync("chg_nonexistent");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        await _gateway.RefundAsync(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await _gateway.RefundAsync("");
    }

    [TestMethod]
    public async Task RefundAsync_DuplicateRefund_Fails()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 50m);
        await _gateway.RefundAsync(charge.ChargeId);
        var second = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsFalse(second.Success);
    }

    [TestMethod]
    public async Task RefundAsync_ReturnsUniqueRefundIds()
    {
        var c1 = await _gateway.ChargeAsync("tok_a", 10m);
        var c2 = await _gateway.ChargeAsync("tok_b", 20m);
        var r1 = await _gateway.RefundAsync(c1.ChargeId);
        var r2 = await _gateway.RefundAsync(c2.ChargeId);

        Assert.AreNotEqual(r1.RefundId, r2.RefundId);
    }
}

